-- QR Code único: serviço na avaliação pública, painel por serviço e relatório.
-- Spec: docs/superpowers/specs/2026-10-07-qr-unico-atribuicoes-design.md (§8, §10).
-- Gerado a partir das definições mais recentes de cada função, com alterações pontuais.

create or replace function public.get_public_evaluation_context(_code text)
returns jsonb
language plpgsql
stable security definer
set search_path = public, pg_temp
as $$
declare
  _point public.pontos_avaliacao%rowtype;
  _registry public.cartorios%rowtype;
  _survey public.pesquisas%rowtype;
  _settings public.configuracoes_cartorio%rowtype;
  _questions jsonb;
begin
  if _code is null or length(trim(_code)) < 3 or length(trim(_code)) > 80 then return jsonb_build_object('status','not_found'); end if;
  select * into _point from public.pontos_avaliacao where public_slug=lower(trim(_code)) or lower(codigo)=lower(trim(_code)) order by case when lower(codigo)=lower(trim(_code)) then 0 else 1 end limit 1;
  if not found then return jsonb_build_object('status','not_found'); end if;
  if _point.status <> 'ativo' then return jsonb_build_object('status','inactive'); end if;
  select * into _registry from public.cartorios where id=_point.cartorio_id;
  if not found or _registry.status <> 'ativo' then return jsonb_build_object('status','unavailable'); end if;
  select * into _survey from public.pesquisas where id=_point.pesquisa_id and cartorio_id=_point.cartorio_id;
  if not found or _survey.status <> 'ativa' then return jsonb_build_object('status','unavailable'); end if;
  select * into _settings from public.configuracoes_cartorio where cartorio_id=_point.cartorio_id;
  select coalesce(jsonb_agg(jsonb_build_object('key',q.id,'text',q.texto,'type',q.tipo,'order',q.ordem,'required',q.obrigatoria,'dimension',q.dimensao,'condition',q.condicao,'options',coalesce((select jsonb_agg(jsonb_build_object('value',o.valor,'label',o.texto) order by o.ordem) from public.opcoes_resposta o where o.pergunta_id=q.id),'[]'::jsonb)) order by q.ordem),'[]'::jsonb) into _questions from public.perguntas q where q.pesquisa_id=_survey.id and q.ativa=true;
  if jsonb_array_length(_questions)=0 then return jsonb_build_object('status','unavailable'); end if;
  return jsonb_build_object('status','ready','registryName',_registry.nome_fantasia,'registryOfficialName',_registry.razao_social,'registryTradeName',_registry.nome_fantasia,'services',(select coalesce(jsonb_agg(jsonb_build_object('id',sv.id,'name',sv.nome,'attribution',sv.atribuicao) order by array_position(array['notas','protesto','imoveis','rtd_pj','civil_pn','maritimo','distribuicao']::text[], sv.atribuicao), sv.ordem),'[]'::jsonb) from public.servicos_cartorio sv where sv.cartorio_id=_registry.id and sv.ativo and sv.atribuicao = any(_registry.atribuicoes)),'pointName',_point.nome,'surveyName',_survey.nome,'surveyDescription',_survey.descricao,'settings',jsonb_build_object('allowContactRequest',coalesce(_settings.permite_contato,true),'thankYouMessage',_settings.mensagem_agradecimento,'privacyNoticeVersion',coalesce(_settings.privacy_notice_version,'1.0')),'questions',_questions);
end $$;

CREATE OR REPLACE FUNCTION public.get_onboarding_test_context(_code text,_test_token uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='public','cartoquali_private','pg_temp' AS $$
DECLARE _point public.pontos_avaliacao%rowtype; _registry public.cartorios%rowtype; _survey public.pesquisas%rowtype; _settings public.configuracoes_cartorio%rowtype; _questions jsonb;
BEGIN
 IF _code IS NULL OR length(trim(_code))<3 OR length(trim(_code))>80 OR _test_token IS NULL THEN RETURN jsonb_build_object('status','not_found'); END IF;
 SELECT p.* INTO _point FROM public.pontos_avaliacao p JOIN public.cartorio_onboarding o ON o.point_id=p.id WHERE (p.public_slug=lower(trim(_code)) OR lower(p.codigo)=lower(trim(_code))) AND o.status='READY_FOR_TEST' AND o.blocked_reason=_test_token::text LIMIT 1;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','not_found'); END IF;
 SELECT * INTO _registry FROM public.cartorios WHERE id=_point.cartorio_id;
 SELECT * INTO _survey FROM public.pesquisas WHERE id=_point.pesquisa_id AND cartorio_id=_point.cartorio_id;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','unavailable'); END IF;
 SELECT * INTO _settings FROM public.configuracoes_cartorio WHERE cartorio_id=_point.cartorio_id;
 SELECT coalesce(jsonb_agg(jsonb_build_object('key',q.id,'text',q.texto,'type',q.tipo,'order',q.ordem,'required',q.obrigatoria,'dimension',q.dimensao,'condition',q.condicao,'options',coalesce((SELECT jsonb_agg(jsonb_build_object('value',x.valor,'label',x.texto) ORDER BY x.ordem) FROM public.opcoes_resposta x WHERE x.pergunta_id=q.id),'[]'::jsonb)) ORDER BY q.ordem),'[]'::jsonb) INTO _questions FROM public.perguntas q WHERE q.pesquisa_id=_survey.id AND q.ativa;
 IF jsonb_array_length(_questions)=0 THEN RETURN jsonb_build_object('status','unavailable'); END IF;
 RETURN jsonb_build_object('status','ready','registryName',_registry.nome_fantasia||' · TESTE','pointName',_point.nome,'registryOfficialName',_registry.razao_social,'registryTradeName',_registry.nome_fantasia,'services',(select coalesce(jsonb_agg(jsonb_build_object('id',sv.id,'name',sv.nome,'attribution',sv.atribuicao) order by array_position(array['notas','protesto','imoveis','rtd_pj','civil_pn','maritimo','distribuicao']::text[], sv.atribuicao), sv.ordem),'[]'::jsonb) from public.servicos_cartorio sv where sv.cartorio_id=_registry.id and sv.ativo and sv.atribuicao = any(_registry.atribuicoes)),'surveyName',_survey.nome,'surveyDescription',_survey.descricao,'settings',jsonb_build_object('allowContactRequest',false,'thankYouMessage','Teste concluído. Retorne à implantação para revisar e ativar.','privacyNoticeVersion',coalesce(_settings.privacy_notice_version,'1.0')),'questions',_questions);
END $$;
REVOKE ALL ON FUNCTION public.get_onboarding_test_context(text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_onboarding_test_context(text,uuid) TO service_role;

DROP FUNCTION IF EXISTS public.submit_public_evaluation(text,uuid,text,jsonb,jsonb);
CREATE FUNCTION public.submit_public_evaluation(_code text, _idempotency_key uuid, _source_hash text, _answers jsonb, _contact jsonb DEFAULT '{}'::jsonb, _servico_id uuid DEFAULT NULL, _servico_outro boolean DEFAULT false)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'cartoquali_private', 'pg_temp'
AS $function$
declare
  _point public.pontos_avaliacao%rowtype;
  _survey public.pesquisas%rowtype;
  _registry_status text;
  _question public.perguntas%rowtype;
  _answer jsonb;
  _answer_text text;
  _evaluation_id uuid:=gen_random_uuid();
  _rating smallint;
  _resolution text;
  _comment text;
  _improvements text;
  _wants_contact boolean:=coalesce((_contact->>'requested')::boolean,false);
  _name text:=nullif(trim(_contact->>'name'),'');
  _phone text:=nullif(trim(_contact->>'phone'),'');
  _email text:=nullif(trim(_contact->>'email'),'');
  _condition_source text;
  _condition_operator text;
  _condition_value jsonb;
  _condition_answer jsonb;
  _visible boolean;
  _service uuid;
  _active_services integer;
begin
  if _code is null or length(trim(_code))<3 or length(trim(_code))>80 or _idempotency_key is null or _source_hash is null or length(_source_hash)<>64 then raise exception 'invalid_request' using errcode='22023'; end if;
  if _answers is null or jsonb_typeof(_answers)<>'object' or (select count(*) from jsonb_object_keys(_answers))>50 or pg_column_size(_answers)>32768 or pg_column_size(_contact)>4096 then raise exception 'invalid_request' using errcode='22023'; end if;
  if exists(select 1 from cartoquali_private.public_submission_guards where idempotency_key=_idempotency_key) then return jsonb_build_object('ok',true,'duplicate',true); end if;
  if (select count(*) from cartoquali_private.public_submission_guards where source_hash=_source_hash and created_at>now()-interval '10 minutes')>=8 then raise exception 'rate_limited' using errcode='P0001'; end if;
  select * into _point from public.pontos_avaliacao where public_slug=lower(trim(_code)) or lower(codigo)=lower(trim(_code)) order by case when lower(codigo)=lower(trim(_code)) then 0 else 1 end limit 1;
  if not found then raise exception 'point_not_found' using errcode='P0001'; end if;
  if _point.status<>'ativo' then raise exception 'point_inactive' using errcode='P0001'; end if;
  select status into _registry_status from public.cartorios where id=_point.cartorio_id;
  if _registry_status is distinct from 'ativo' then raise exception 'survey_unavailable' using errcode='P0001'; end if;
  select * into _survey from public.pesquisas where id=_point.pesquisa_id and cartorio_id=_point.cartorio_id and status='ativa';
  if not found then raise exception 'survey_unavailable' using errcode='P0001'; end if;
  if not coalesce((select permite_contato from public.configuracoes_cartorio where cartorio_id=_point.cartorio_id),true) then _wants_contact:=false; end if;
  -- Serviço informado (opcional): precisa ser do mesmo cartório, ativo e de atribuição marcada.
  if _servico_id is not null then
    if not exists(select 1 from public.servicos_cartorio sv join public.cartorios ct on ct.id=sv.cartorio_id where sv.id=_servico_id and sv.cartorio_id=_point.cartorio_id and sv.ativo and sv.atribuicao=any(ct.atribuicoes)) then raise exception 'service_unavailable' using errcode='P0001'; end if;
    _service:=_servico_id; _servico_outro:=false;
  elsif not coalesce(_servico_outro,false) then
    select count(*) into _active_services from public.servicos_cartorio sv join public.cartorios ct on ct.id=sv.cartorio_id where sv.cartorio_id=_point.cartorio_id and sv.ativo and sv.atribuicao=any(ct.atribuicoes);
    if _active_services=1 then select sv.id into _service from public.servicos_cartorio sv join public.cartorios ct on ct.id=sv.cartorio_id where sv.cartorio_id=_point.cartorio_id and sv.ativo and sv.atribuicao=any(ct.atribuicoes); end if;
  end if;
  for _question in select * from public.perguntas where pesquisa_id=_survey.id and ativa=true order by ordem loop
    _answer:=_answers->_question.id::text;
    _visible:=true;
    if _question.condicao is not null then
      _condition_source:=coalesce(_question.condicao->>'sourceQuestionId',_question.condicao->>'source_question_id');
      _condition_operator:=coalesce(_question.condicao->>'operator','eq');
      _condition_value:=_question.condicao->'value';
      _condition_answer:=_answers->_condition_source;
      if _condition_operator='lte' then
        _visible:=jsonb_typeof(_condition_answer)='number' and (_condition_answer#>>'{}')::numeric<=(_condition_value#>>'{}')::numeric;
      else
        _visible:=_condition_answer=_condition_value or (_condition_answer#>>'{}')=(_condition_value#>>'{}');
      end if;
    end if;
    if _visible and _question.obrigatoria and (_answer is null or _answer in ('null'::jsonb,'""'::jsonb,'[]'::jsonb)) then raise exception 'required_answer_missing' using errcode='22023'; end if;
    if not _visible or _answer is null or _answer in ('null'::jsonb,'""'::jsonb,'[]'::jsonb) then continue; end if;
    if _question.tipo in ('stars','scale') then
      if jsonb_typeof(_answer)<>'number' or (_answer#>>'{}')::numeric not between 1 and 5 then raise exception 'invalid_answer' using errcode='22023'; end if;
      if _question.dimensao='overall' and _rating is null then _rating:=(_answer#>>'{}')::smallint; end if;
    elsif _question.tipo='yes_no' then
      if not exists(select 1 from public.opcoes_resposta o where o.pergunta_id=_question.id and (to_jsonb(o.valor)=_answer or to_jsonb(o.texto)=_answer)) and (_answer#>>'{}') not in ('Sim','Não','sim','nao','não','Parcialmente','parcialmente') then raise exception 'invalid_answer' using errcode='22023'; end if;
    elsif _question.tipo='single_choice' then
      if jsonb_typeof(_answer)<>'string' or not exists(select 1 from public.opcoes_resposta o where o.pergunta_id=_question.id and (to_jsonb(o.valor)=_answer or to_jsonb(o.texto)=_answer)) then raise exception 'invalid_option' using errcode='22023'; end if;
    elsif _question.tipo='multiple_choice' then
      if jsonb_typeof(_answer)<>'array' or jsonb_array_length(_answer)>20 or exists(select 1 from jsonb_array_elements_text(_answer) v where length(v.value)>200 or not exists(select 1 from public.opcoes_resposta o where o.pergunta_id=_question.id and (o.valor=v.value or o.texto=v.value))) then raise exception 'invalid_option' using errcode='22023'; end if;
    elsif _question.tipo='text' then
      if jsonb_typeof(_answer)<>'string' or length(_answer#>>'{}')>1000 then raise exception 'invalid_answer' using errcode='22023'; end if;
    else raise exception 'invalid_question_type' using errcode='22023'; end if;
    _answer_text:=case when jsonb_typeof(_answer)='string' then _answer#>>'{}' else null end;
    if _question.dimensao='resolution' then _resolution:=case lower(coalesce(_answer_text,'')) when 'sim' then 'sim' when 'parcialmente' then 'parcialmente' when 'não' then 'nao' when 'nao' then 'nao' else null end; end if;
    if _question.tipo='text' and _question.dimensao='comment' then _comment:=nullif(trim(_answer_text),''); end if;
    if _question.tipo='multiple_choice' and _question.dimensao='comment' then _improvements:=array_to_string(array(select jsonb_array_elements_text(_answer)),', '); end if;
  end loop;
  if exists(select 1 from jsonb_object_keys(_answers) supplied(key) where not exists(select 1 from public.perguntas q where q.id::text=supplied.key and q.pesquisa_id=_survey.id and q.ativa=true)) then raise exception 'unknown_question' using errcode='22023'; end if;
  if _rating is null then select (_answers->q.id::text#>>'{}')::smallint into _rating from public.perguntas q where q.pesquisa_id=_survey.id and q.ativa and q.tipo in ('stars','scale') and _answers?q.id::text order by q.ordem limit 1; end if;
  if _rating is null or _rating not between 1 and 5 then raise exception 'rating_required' using errcode='22023'; end if;
  if _wants_contact then
    if (_phone is null and _email is null) or coalesce(length(_name),0)>100 or coalesce(length(_phone),0)>30 or coalesce(length(_email),0)>255 or (_email is not null and _email!~*'^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$') then raise exception 'invalid_contact' using errcode='22023'; end if;
  else _name:=null; _phone:=null; _email:=null; end if;
  insert into cartoquali_private.public_submission_guards(idempotency_key,source_hash) values(_idempotency_key,_source_hash);
  insert into public.avaliacoes(id,cartorio_id,ponto_id,pesquisa_id,nota_geral,atendimento_resolvido,comentario,motivo_insatisfacao,deseja_contato,nome_contato,telefone_contato,email_contato,anonymous,status,servico_id,servico_outro) values(_evaluation_id,_point.cartorio_id,_point.id,_survey.id,_rating,_resolution,_comment,_improvements,_wants_contact,_name,_phone,_email,not _wants_contact,'nova',_service,coalesce(_servico_outro,false));
  insert into public.respostas(avaliacao_id,pergunta_id,valor,resposta_texto) select _evaluation_id,q.id,_answers->q.id::text,case when jsonb_typeof(_answers->q.id::text)='string' then _answers->q.id::text#>>'{}' else null end from public.perguntas q where q.pesquisa_id=_survey.id and q.ativa=true and _answers?q.id::text and _answers->q.id::text not in ('null'::jsonb,'""'::jsonb,'[]'::jsonb);
  delete from cartoquali_private.public_submission_guards where created_at<now()-interval '1 day';
  return jsonb_build_object('ok',true,'duplicate',false);
end $function$;
REVOKE ALL ON FUNCTION public.submit_public_evaluation(text,uuid,text,jsonb,jsonb,uuid,boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.submit_public_evaluation(text,uuid,text,jsonb,jsonb,uuid,boolean) TO service_role;

DROP FUNCTION IF EXISTS public.get_dashboard_indicators(timestamptz,timestamptz,timestamptz,timestamptz,uuid,uuid,text);
CREATE FUNCTION public.get_dashboard_indicators(_current_start timestamptz,_current_end timestamptz,_previous_start timestamptz,_previous_end timestamptz,_point_id uuid DEFAULT NULL,_survey_id uuid DEFAULT NULL,_granularity text DEFAULT 'day',_servico_id uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path='public','pg_temp' AS $$
DECLARE _result jsonb;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
 IF _current_start IS NULL OR _current_end IS NULL OR _previous_start IS NULL OR _previous_end IS NULL OR _current_start>=_current_end OR _previous_start>=_previous_end OR _granularity NOT IN ('day','week','month') THEN RAISE EXCEPTION 'invalid_request' USING ERRCODE='22023'; END IF;
 WITH current_evaluations AS (SELECT a.* FROM public.avaliacoes a WHERE NOT a.is_test AND a.created_at>=_current_start AND a.created_at<_current_end AND (_point_id IS NULL OR a.ponto_id=_point_id) AND (_survey_id IS NULL OR a.pesquisa_id=_survey_id) AND (_servico_id IS NULL OR a.servico_id=_servico_id)),previous_evaluations AS (SELECT a.* FROM public.avaliacoes a WHERE NOT a.is_test AND a.created_at>=_previous_start AND a.created_at<_previous_end AND (_point_id IS NULL OR a.ponto_id=_point_id) AND (_survey_id IS NULL OR a.pesquisa_id=_survey_id) AND (_servico_id IS NULL OR a.servico_id=_servico_id)),current_summary AS (SELECT count(*)::int total,round(avg(nota_geral)::numeric,2) average,round((count(*) filter(where nota_geral>=4)*100.0/nullif(count(*),0))::numeric,2) satisfaction,round((count(*) filter(where nota_geral<=3)*100.0/nullif(count(*),0))::numeric,2) negative_rate,count(*) filter(where nota_geral<=3)::int negative_count,count(*) filter(where comentario is not null and btrim(comentario)<>'')::int comments,count(*) filter(where deseja_contato)::int contact_requests,round((count(*) filter(where atendimento_resolvido='sim')*100.0/nullif(count(*) filter(where atendimento_resolvido is not null),0))::numeric,2) resolution FROM current_evaluations),previous_summary AS (SELECT count(*)::int total,round(avg(nota_geral)::numeric,2) average,round((count(*) filter(where nota_geral>=4)*100.0/nullif(count(*),0))::numeric,2) satisfaction,round((count(*) filter(where nota_geral<=3)*100.0/nullif(count(*),0))::numeric,2) negative_rate,count(*) filter(where nota_geral<=3)::int negative_count,count(*) filter(where comentario is not null and btrim(comentario)<>'')::int comments,count(*) filter(where deseja_contato)::int contact_requests,round((count(*) filter(where atendimento_resolvido='sim')*100.0/nullif(count(*) filter(where atendimento_resolvido is not null),0))::numeric,2) resolution FROM previous_evaluations),distribution AS (SELECT r.rating,count(c.id)::int count FROM generate_series(1,5) r(rating) LEFT JOIN current_evaluations c ON c.nota_geral=r.rating GROUP BY r.rating),series AS (SELECT date_trunc(_granularity,c.created_at at time zone 'America/Sao_Paulo') bucket,count(*)::int total,round(avg(c.nota_geral)::numeric,2) average,round((count(*) filter(where c.nota_geral>=4)*100.0/count(*))::numeric,2) satisfaction,round((count(*) filter(where c.nota_geral<=3)*100.0/count(*))::numeric,2) negative_rate,round((count(*) filter(where c.atendimento_resolvido='sim')*100.0/nullif(count(*) filter(where c.atendimento_resolvido is not null),0))::numeric,2) resolution FROM current_evaluations c GROUP BY 1),point_performance AS (SELECT p.id,p.nome name,count(c.id)::int total,round(avg(c.nota_geral)::numeric,2) average,round((count(c.id) filter(where c.nota_geral>=4)*100.0/nullif(count(c.id),0))::numeric,2) satisfaction,round((count(c.id) filter(where c.nota_geral<=3)*100.0/nullif(count(c.id),0))::numeric,2) negative_rate FROM public.pontos_avaliacao p LEFT JOIN current_evaluations c ON c.ponto_id=p.id WHERE (_point_id IS NULL OR p.id=_point_id) AND (_survey_id IS NULL OR p.pesquisa_id=_survey_id) GROUP BY p.id,p.nome),current_dimension_values AS (SELECT lower(q.dimensao) dimension,CASE WHEN q.tipo IN ('stars','scale') AND jsonb_typeof(r.valor)='number' THEN (r.valor#>>'{}')::numeric WHEN q.tipo='yes_no' AND lower(coalesce(r.valor#>>'{}',r.resposta_texto,'')) IN ('sim','yes','true') THEN 5 WHEN q.tipo='yes_no' AND lower(coalesce(r.valor#>>'{}',r.resposta_texto,'')) IN ('parcialmente','partial') THEN 3 WHEN q.tipo='yes_no' AND lower(coalesce(r.valor#>>'{}',r.resposta_texto,'')) IN ('não','nao','no','false') THEN 1 END score FROM public.respostas r JOIN current_evaluations e ON e.id=r.avaliacao_id JOIN public.perguntas q ON q.id=r.pergunta_id AND q.pesquisa_id=e.pesquisa_id WHERE q.dimensao IN ('service','time','clarity','resolution','structure')),previous_dimension_values AS (SELECT lower(q.dimensao) dimension,CASE WHEN q.tipo IN ('stars','scale') AND jsonb_typeof(r.valor)='number' THEN (r.valor#>>'{}')::numeric WHEN q.tipo='yes_no' AND lower(coalesce(r.valor#>>'{}',r.resposta_texto,'')) IN ('sim','yes','true') THEN 5 WHEN q.tipo='yes_no' AND lower(coalesce(r.valor#>>'{}',r.resposta_texto,'')) IN ('parcialmente','partial') THEN 3 WHEN q.tipo='yes_no' AND lower(coalesce(r.valor#>>'{}',r.resposta_texto,'')) IN ('não','nao','no','false') THEN 1 END score FROM public.respostas r JOIN previous_evaluations e ON e.id=r.avaliacao_id JOIN public.perguntas q ON q.id=r.pergunta_id AND q.pesquisa_id=e.pesquisa_id WHERE q.dimensao IN ('service','time','clarity','resolution','structure')),current_dimensions AS (SELECT dimension,count(score)::int responses,round((avg(score)/5*100)::numeric,2) index FROM current_dimension_values WHERE score BETWEEN 1 AND 5 GROUP BY dimension),previous_dimensions AS (SELECT dimension,count(score)::int responses,round((avg(score)/5*100)::numeric,2) index FROM previous_dimension_values WHERE score BETWEEN 1 AND 5 GROUP BY dimension),dimension_keys AS (SELECT * FROM (VALUES('service','Cordialidade'),('time','Tempo'),('clarity','Clareza'),('resolution','Resolutividade'),('structure','Instalações')) d(key,label)),dimensions AS (SELECT d.key,d.label,coalesce(c.responses,0) responses,c.index,coalesce(p.responses,0) previous_responses,p.index previous_index FROM dimension_keys d LEFT JOIN current_dimensions c ON c.dimension=d.key LEFT JOIN previous_dimensions p ON p.dimension=d.key),service_performance AS (SELECT CASE WHEN c.servico_id IS NOT NULL THEN c.servico_id::text WHEN c.servico_outro THEN 'outro' ELSE 'nao_informado' END id,coalesce(sv.nome,CASE WHEN c.servico_outro THEN 'Outro serviço' ELSE 'Serviço não informado' END) name,count(*)::int total,round(avg(c.nota_geral)::numeric,2) average,round((count(*) filter(where c.nota_geral<=3)*100.0/nullif(count(*),0))::numeric,2) negative_rate FROM current_evaluations c LEFT JOIN public.servicos_cartorio sv ON sv.id=c.servico_id GROUP BY 1,2),recent AS (SELECT c.id,c.nota_geral rating,c.comentario comment,c.created_at,p.nome point_name,rsv.nome service_name FROM current_evaluations c JOIN public.pontos_avaliacao p ON p.id=c.ponto_id LEFT JOIN public.servicos_cartorio rsv ON rsv.id=c.servico_id ORDER BY c.created_at DESC LIMIT 3),filters AS (SELECT (SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.nome) ORDER BY p.nome),'[]') FROM public.pontos_avaliacao p) points,(SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.nome) ORDER BY s.nome),'[]') FROM public.pesquisas s) surveys,(SELECT coalesce(jsonb_agg(jsonb_build_object('id',sv.id,'name',sv.nome,'attribution',sv.atribuicao) ORDER BY array_position(array['notas','protesto','imoveis','rtd_pj','civil_pn','maritimo','distribuicao']::text[], sv.atribuicao), sv.ordem),'[]') FROM public.servicos_cartorio sv JOIN public.cartorios ct ON ct.id=sv.cartorio_id WHERE sv.atribuicao=any(ct.atribuicoes)) services) SELECT jsonb_build_object('summary',to_jsonb(cs),'previousSummary',to_jsonb(ps),'distribution',(SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.rating),'[]') FROM distribution d),'series',(SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.bucket),'[]') FROM series s),'services',(SELECT coalesce(jsonb_agg(to_jsonb(spf) ORDER BY spf.total desc,spf.name),'[]') FROM service_performance spf),'points',(SELECT coalesce(jsonb_agg(to_jsonb(pp) ORDER BY pp.total desc,pp.name),'[]') FROM point_performance pp),'dimensions',(SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.key),'[]') FROM dimensions d),'recent',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.created_at desc),'[]') FROM recent r),'filters',to_jsonb(f)) INTO _result FROM current_summary cs CROSS JOIN previous_summary ps CROSS JOIN filters f; RETURN _result;
END $$;
REVOKE ALL ON FUNCTION public.get_dashboard_indicators(timestamptz,timestamptz,timestamptz,timestamptz,uuid,uuid,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_dashboard_indicators(timestamptz,timestamptz,timestamptz,timestamptz,uuid,uuid,text,uuid) TO authenticated,service_role;

CREATE OR REPLACE FUNCTION public.get_quality_report(_current_start timestamptz,_current_end timestamptz,_previous_start timestamptz,_previous_end timestamptz,_point_id uuid DEFAULT NULL,_survey_id uuid DEFAULT NULL,_occurrence_status text DEFAULT NULL,_plan_status text DEFAULT NULL,_granularity text DEFAULT 'day') RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path='public','pg_temp' AS $$
DECLARE _result jsonb;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
 IF _current_start IS NULL OR _current_end IS NULL OR _previous_start IS NULL OR _previous_end IS NULL OR _current_start>=_current_end OR _previous_start>=_previous_end OR _granularity NOT IN ('day','week','month') OR (_occurrence_status IS NOT NULL AND _occurrence_status NOT IN ('nova','em_analise','em_tratamento','resolvida','encerrada')) OR (_plan_status IS NOT NULL AND _plan_status NOT IN ('planejado','em_andamento','concluido','cancelado')) THEN RAISE EXCEPTION 'invalid_request' USING ERRCODE='22023'; END IF;
 WITH current_evaluations AS MATERIALIZED (SELECT a.* FROM public.avaliacoes a WHERE NOT a.is_test AND a.created_at>=_current_start AND a.created_at<_current_end AND (_point_id IS NULL OR a.ponto_id=_point_id) AND (_survey_id IS NULL OR a.pesquisa_id=_survey_id)),previous_evaluations AS MATERIALIZED (SELECT a.* FROM public.avaliacoes a WHERE NOT a.is_test AND a.created_at>=_previous_start AND a.created_at<_previous_end AND (_point_id IS NULL OR a.ponto_id=_point_id) AND (_survey_id IS NULL OR a.pesquisa_id=_survey_id)),current_occurrences AS MATERIALIZED (SELECT o.* FROM public.ocorrencias_qualidade o WHERE o.data_abertura>=_current_start AND o.data_abertura<_current_end AND (_point_id IS NULL OR o.ponto_id=_point_id) AND (_survey_id IS NULL OR EXISTS(SELECT 1 FROM current_evaluations e WHERE e.id=o.avaliacao_id)) AND (_occurrence_status IS NULL OR o.status=_occurrence_status)),current_plans AS MATERIALIZED (SELECT p.* FROM public.planos_melhoria p WHERE p.created_at>=_current_start AND p.created_at<_current_end AND (_point_id IS NULL OR p.ponto_id=_point_id) AND (_survey_id IS NULL OR EXISTS(SELECT 1 FROM current_occurrences o JOIN current_evaluations e ON e.id=o.avaliacao_id WHERE o.id=p.ocorrencia_id)) AND (_plan_status IS NULL OR p.status=_plan_status)),summary AS (SELECT count(*)::int total,round(avg(nota_geral)::numeric,2) average,round((count(*) FILTER(WHERE nota_geral>=4)*100.0/nullif(count(*),0))::numeric,2) satisfaction,round((count(*) FILTER(WHERE nota_geral<=3)*100.0/nullif(count(*),0))::numeric,2) negative_rate,count(*) FILTER(WHERE nota_geral<=3)::int negative_count,count(*) FILTER(WHERE comentario IS NOT NULL AND btrim(comentario)<>'')::int comments,round((count(*) FILTER(WHERE atendimento_resolvido='sim')*100.0/nullif(count(*) FILTER(WHERE atendimento_resolvido IS NOT NULL),0))::numeric,2) resolution FROM current_evaluations),previous_summary AS (SELECT count(*)::int total,round(avg(nota_geral)::numeric,2) average,round((count(*) FILTER(WHERE nota_geral>=4)*100.0/nullif(count(*),0))::numeric,2) satisfaction,round((count(*) FILTER(WHERE nota_geral<=3)*100.0/nullif(count(*),0))::numeric,2) negative_rate,count(*) FILTER(WHERE nota_geral<=3)::int negative_count,round((count(*) FILTER(WHERE atendimento_resolvido='sim')*100.0/nullif(count(*) FILTER(WHERE atendimento_resolvido IS NOT NULL),0))::numeric,2) resolution FROM previous_evaluations),management AS (SELECT (SELECT count(*)::int FROM current_occurrences) occurrences_total,(SELECT count(*)::int FROM current_occurrences WHERE status IN ('resolvida','encerrada')) occurrences_resolved,(SELECT count(*)::int FROM current_plans) plans_total,(SELECT count(*)::int FROM current_plans WHERE status='concluido') plans_completed,(SELECT count(*)::int FROM current_plans WHERE status='em_andamento') plans_active,(SELECT count(*)::int FROM current_plans WHERE status NOT IN ('concluido','cancelado') AND prazo<(now() AT TIME ZONE 'America/Sao_Paulo')::date) plans_overdue),distribution AS (SELECT n.rating,count(e.id)::int count FROM generate_series(1,5)n(rating) LEFT JOIN current_evaluations e ON e.nota_geral=n.rating GROUP BY n.rating),series AS (SELECT date_trunc(_granularity,e.created_at AT TIME ZONE 'America/Sao_Paulo') bucket,count(*)::int total,round(avg(e.nota_geral)::numeric,2) average,round((count(*) FILTER(WHERE e.nota_geral>=4)*100.0/count(*))::numeric,2) satisfaction,round((count(*) FILTER(WHERE e.nota_geral<=3)*100.0/count(*))::numeric,2) negative_rate FROM current_evaluations e GROUP BY 1),point_performance AS (SELECT p.id,p.nome name,count(e.id)::int total,round(avg(e.nota_geral)::numeric,2) average,round((count(e.id) FILTER(WHERE e.nota_geral>=4)*100.0/nullif(count(e.id),0))::numeric,2) satisfaction,round((count(e.id) FILTER(WHERE e.nota_geral<=3)*100.0/nullif(count(e.id),0))::numeric,2) negative_rate FROM public.pontos_avaliacao p LEFT JOIN current_evaluations e ON e.ponto_id=p.id WHERE (_point_id IS NULL OR p.id=_point_id) AND (_survey_id IS NULL OR p.pesquisa_id=_survey_id) GROUP BY p.id,p.nome HAVING count(e.id)>0),current_dimension_values AS (SELECT lower(q.dimensao) dimension,CASE WHEN q.tipo IN ('stars','scale') AND jsonb_typeof(r.valor)='number' THEN (r.valor#>>'{}')::numeric WHEN q.tipo='yes_no' AND lower(coalesce(r.valor#>>'{}',r.resposta_texto,'')) IN ('sim','yes','true') THEN 5 WHEN q.tipo='yes_no' AND lower(coalesce(r.valor#>>'{}',r.resposta_texto,'')) IN ('parcialmente','partial') THEN 3 WHEN q.tipo='yes_no' AND lower(coalesce(r.valor#>>'{}',r.resposta_texto,'')) IN ('não','nao','no','false') THEN 1 END score FROM public.respostas r JOIN current_evaluations e ON e.id=r.avaliacao_id JOIN public.perguntas q ON q.id=r.pergunta_id AND q.pesquisa_id=e.pesquisa_id WHERE q.dimensao IN ('service','time','clarity','resolution','structure')),previous_dimension_values AS (SELECT lower(q.dimensao) dimension,CASE WHEN q.tipo IN ('stars','scale') AND jsonb_typeof(r.valor)='number' THEN (r.valor#>>'{}')::numeric WHEN q.tipo='yes_no' AND lower(coalesce(r.valor#>>'{}',r.resposta_texto,'')) IN ('sim','yes','true') THEN 5 WHEN q.tipo='yes_no' AND lower(coalesce(r.valor#>>'{}',r.resposta_texto,'')) IN ('parcialmente','partial') THEN 3 WHEN q.tipo='yes_no' AND lower(coalesce(r.valor#>>'{}',r.resposta_texto,'')) IN ('não','nao','no','false') THEN 1 END score FROM public.respostas r JOIN previous_evaluations e ON e.id=r.avaliacao_id JOIN public.perguntas q ON q.id=r.pergunta_id AND q.pesquisa_id=e.pesquisa_id WHERE q.dimensao IN ('service','time','clarity','resolution','structure')),dimension_keys AS (SELECT * FROM (VALUES('service','Cordialidade'),('time','Tempo'),('clarity','Clareza'),('resolution','Resolutividade'),('structure','Instalações'))d(key,label)),current_dimensions AS (SELECT dimension,count(score)::int responses,round((avg(score)/5*100)::numeric,2) index FROM current_dimension_values WHERE score BETWEEN 1 AND 5 GROUP BY dimension),previous_dimensions AS (SELECT dimension,count(score)::int responses,round((avg(score)/5*100)::numeric,2) index FROM previous_dimension_values WHERE score BETWEEN 1 AND 5 GROUP BY dimension),dimensions AS (SELECT d.key,d.label,coalesce(c.responses,0) responses,c.index,coalesce(p.responses,0) previous_responses,p.index previous_index FROM dimension_keys d LEFT JOIN current_dimensions c ON c.dimension=d.key LEFT JOIN previous_dimensions p ON p.dimension=d.key),evaluations_detail AS (SELECT e.id,e.created_at,e.nota_geral rating,e.atendimento_resolvido resolution,e.comentario comment,e.status,p.id point_id,p.nome point_name,rsv.nome service_name,s.id survey_id,s.nome survey_name FROM current_evaluations e JOIN public.pontos_avaliacao p ON p.id=e.ponto_id LEFT JOIN public.servicos_cartorio rsv ON rsv.id=e.servico_id JOIN public.pesquisas s ON s.id=e.pesquisa_id ORDER BY e.created_at DESC LIMIT 5000),occurrences_detail AS (SELECT o.id,o.avaliacao_id evaluation_id,o.ponto_id,o.titulo title,o.categoria category,o.descricao description,o.prioridade priority,o.status,o.origem origin,o.prazo due_date,o.data_abertura opened_at,o.data_resolucao resolved_at,u.nome owner FROM current_occurrences o LEFT JOIN public.usuarios u ON u.id=o.responsavel_id ORDER BY o.data_abertura DESC LIMIT 2000),plans_detail AS (SELECT p.id,p.ocorrencia_id occurrence_id,p.ponto_id,p.dimensao dimension,p.titulo title,p.problema problem,p.objetivo objective,p.acao action,p.prioridade priority,p.prazo due_date,p.status,p.progresso progress,p.resultado_esperado expected_result,p.resultado result,p.observacao_resultado result_observation,p.indicador_nome indicator_name,p.indicador_antes indicator_before,p.indicador_depois indicator_after,p.concluido_em completed_at,p.created_at,p.updated_at,u.nome owner FROM current_plans p LEFT JOIN public.usuarios u ON u.id=p.responsavel_id ORDER BY p.created_at DESC LIMIT 2000),occurrence_groups AS (SELECT 'status' kind,status label,count(*)::int count FROM current_occurrences GROUP BY status UNION ALL SELECT 'category',categoria,count(*)::int FROM current_occurrences GROUP BY categoria UNION ALL SELECT 'priority',prioridade,count(*)::int FROM current_occurrences GROUP BY prioridade),plan_groups AS (SELECT status label,count(*)::int count FROM current_plans GROUP BY status),evidence_chain AS (SELECT e.id evaluation_id,e.created_at evaluation_date,e.nota_geral rating,e.comentario comment,p.nome point_name,o.id occurrence_id,o.titulo occurrence_title,o.categoria occurrence_category,o.status occurrence_status,o.descricao treatment,pl.id plan_id,pl.problema plan_problem,pl.acao plan_action,pl.prazo plan_due_date,pl.status plan_status,pl.resultado plan_result,u.nome responsible FROM current_evaluations e JOIN public.pontos_avaliacao p ON p.id=e.ponto_id LEFT JOIN public.ocorrencias_qualidade o ON o.avaliacao_id=e.id LEFT JOIN public.planos_melhoria pl ON pl.ocorrencia_id=o.id LEFT JOIN public.usuarios u ON u.id=pl.responsavel_id WHERE e.nota_geral<=3 OR o.id IS NOT NULL ORDER BY e.created_at DESC LIMIT 500),filters AS (SELECT (SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.nome,'surveyId',p.pesquisa_id) ORDER BY p.nome),'[]') FROM public.pontos_avaliacao p) points,(SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.nome) ORDER BY s.nome),'[]') FROM public.pesquisas s) surveys),registry AS (SELECT id,nome_fantasia trade_name,razao_social official_name FROM public.cartorios LIMIT 1) SELECT jsonb_build_object('registry',to_jsonb(r),'summary',to_jsonb(s),'previousSummary',to_jsonb(ps),'management',to_jsonb(m),'distribution',(SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.rating),'[]') FROM distribution d),'series',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.bucket),'[]') FROM series x),'points',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.total DESC,x.name),'[]') FROM point_performance x),'dimensions',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.key),'[]') FROM dimensions x),'evaluations',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC),'[]') FROM evaluations_detail x),'occurrences',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.opened_at DESC),'[]') FROM occurrences_detail x),'plans',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC),'[]') FROM plans_detail x),'occurrenceGroups',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.kind,x.count DESC),'[]') FROM occurrence_groups x),'planGroups',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.count DESC),'[]') FROM plan_groups x),'evidence',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.evaluation_date DESC),'[]') FROM evidence_chain x),'filters',to_jsonb(f)) INTO _result FROM registry r CROSS JOIN summary s CROSS JOIN previous_summary ps CROSS JOIN management m CROSS JOIN filters f; RETURN coalesce(_result,'{}'::jsonb);
END $$;
REVOKE ALL ON FUNCTION public.get_quality_report(timestamptz,timestamptz,timestamptz,timestamptz,uuid,uuid,text,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_quality_report(timestamptz,timestamptz,timestamptz,timestamptz,uuid,uuid,text,text,text) TO authenticated,service_role;
